reg [C_AXIL_ADDR_WIDTH-1:0] src_addr;
reg [C_AXIL_ADDR_WIDTH-1:0] dst_addr;
reg [C_AXIL_ADDR_WIDTH-1:0] length;
reg [C_AXIL_ADDR_WIDTH-1:0] current_length;
reg [C_AXIL_ADDR_WIDTH-1:0] current_src_addr;
reg [C_AXIL_ADDR_WIDTH-1:0] current_dst_addr;
reg start_transfer;
reg transfer_done;

always @(posedge S_AXI_ACLK) begin
    if (!S_AXI_ARESETN) begin
        src_addr <= 0;
        dst_addr <= 0;
        length <= 0;
        current_length <= 0;
        current_src_addr <= 0;
        current_dst_addr <= 0;
        start_transfer <= 0;
        transfer_done <= 0;
    end else begin
        if (S_AXIL_AWVALID && S_AXIL_WVALID) begin
            case (S_AXIL_AWADDR)
                5'h0: src_addr <= S_AXIL_WDATA;
                5'h4: dst_addr <= S_AXIL_WDATA;
                5'h8: length <= S_AXIL_WDATA;
                default: ;
            endcase
        end

        if (S_AXIL_BREADY && S_AXIL_BVALID) begin
            S_AXIL_BVALID <= 0;
        end

        if (S_AXIL_ARVALID) begin
            case (S_AXIL_ARADDR)
                5'h0: S_AXIL_RDATA <= src_addr;
                5'h4: S_AXIL_RDATA <= dst_addr;
                5'h8: S_AXIL_RDATA <= length;
                default: ;
            endcase
            S_AXIL_RVALID <= 1;
        end

        if (S_AXIL_RREADY && S_AXIL_RVALID) begin
            S_AXIL_RVALID <= 0;
        end

        if (start_transfer &&!transfer_done) begin
            if (current_length == 0) begin
                transfer_done <= 1;
            end else begin
                M_AXI_AWVALID <= 1;
                M_AXI_AWADDR <= current_src_addr;
                M_AXI_AWSIZE <= 2'b10;
                M_AXI_AWBURST <= 2'b01;
                M_AXI_AWLOCK <= 0;
                M_AXI_AWCACHE <= 4'b1111;
                M_AXI_AWPROT <= 3'b000;
                M_AXI_AWQOS <= 4'b0000;
                M_AXI_WVALID <= 1;
                M_AXI_WDATA <= 0;
                M_AXI_WSTRB <= {C_AXI_DATA_WIDTH/8{1'b1}};
                M_AXI_WLAST <= 1;
                current_src_addr <= current_src_addr + C_AXI_DATA_WIDTH/8;
                current_dst_addr <= current_dst_addr + C_AXI_DATA_WIDTH/8;
                current_length <= current_length - 1;
            end
        end

        if (M_AXI_BVALID) begin
            M_AXI_BREADY <= 1;
        end

        if (M_AXI_BREADY && M_AXI_BVALID) begin
            M_AXI_BREADY <= 0;
        end

        if (M_AXI_RVALID) begin
            M_AXI_RREADY <= 1;
        end

        if (M_AXI_RREADY && M_AXI_RVALID) begin
            M_AXI_RREADY <= 0;
        end

        if (S_AXIL_AWVALID && S_AXIL_WVALID && S_AXIL_AWADDR == 5'hc) begin
            start_transfer <= 1;
            current_src_addr <= src_addr;
            current_dst_addr <= dst_addr;
            current_length <= length;
        end
    end
end

assign S_AXIL_AWREADY = 1;
assign S_AXIL_WREADY = 1;
assign S_AXIL_BRESP = 2'b00;
assign S_AXIL_RRESP = 2'b00;
assign M_AXI_ARVALID = 0;
assign M_AXI_ARADDR = 0;
assign M_AXI_ARSIZE = 3'b010;
assign M_AXI_ARBURST = 2'b01;
assign M_AXI_ARLOCK = 0;
assign M_AXI_ARCACHE = 4'b1111;
assign M_AXI_ARPROT = 3'b000;
assign M_AXI_ARQOS = 4'b0000;
assign M_AXI_ARID = AXI_READ_ID;
assign o_int = 0;

endmodule
